  const seen = new Set();
  const result = [];
  for (const value of values) {
    if (!seen.has(value)) {
      seen.add(value);
      result.push(value);
    }
  }
  return result;
}

import { uniqueStrings } from './unique_repeat.mjs';

const input = ['a', 'b', 'a', 'c', 'b', 'A'];
const result = uniqueStrings(input);
console.log(JSON.stringify(result));
console.log(JSON.stringify(input));

if (JSON.stringify(result) !== JSON.stringify(['a', 'b', 'c', 'A'])) {
  throw new Error('Unexpected result');
}
if (JSON.stringify(input) !== JSON.stringify(['a', 'b', 'a', 'c', 'b', 'A'])) {
  throw new Error('Input was mutated');
}

const whitespace = [' x ', 'x', ' x '];
const wsResult = uniqueStrings(whitespace);
if (JSON.stringify(wsResult) !== JSON.stringify([' x ', 'x'])) {
  throw new Error('Whitespace handling failed');
}

console.log('All checks passed');

